import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long r = in.nextLong();
        long k = in.nextLong();
        long tanlov = 1;
        for (long i = 0; i < k; i++) {
            tanlov *= r - i;
        }
        long holat = 1;
        for (long i = 0; i < k; i++) {
            holat *= 26;
        }
        System.out.println(tanlov);
        System.out.println(holat);
    }
}

